  <script>
	    let documents = [];
	    const routes = { data:@json(route($routePrefix.'.documents.data')), send:@json(route($routePrefix.'.send')), cancel:@json(route($routePrefix.'.cancel')), delete:@json(route($routePrefix.'.delete')) };
	    const statusMap={DRAFT:{label:'Draft',tone:'draft'},WAITING:{label:'ລໍຖ້າ',tone:'waiting'},QWAIT:{label:'ລໍຖ້າ',tone:'waiting'},POINTING:{label:'ກຳລັງລະບຸສາຍທາງ',tone:'processing'},SIGNING:{label:'ກຳລັງດຳເນີນການ',tone:'processing'},QSIGNING:{label:'ກຳລັງດຳເນີນການ',tone:'processing'},SIGNINED:{label:'ລົງລາຍເຊັນແລ້ວ',tone:'ready'},READY:{label:'ພ້ອມສົ່ງມອບ',tone:'ready'},SUCCESS:{label:'ສຳເລັດ',tone:'success'},CANCEL:{label:'ຍົກເລີກ',tone:'cancel'}}; let state={scope:'today',filter:'ALL',q:'',page:1,pagination:{current_page:1,last_page:1,total:0,from:null,to:null},loading:false}; const $=s=>document.querySelector(s); const $$=s=>Array.from(document.querySelectorAll(s)); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
	    function chip(s){const m=statusMap[s]||{label:s,tone:'draft'};return `<span class="status-chip status-${m.tone}">${esc(m.label)}</span>`} function files(d){return d.files.length?`<div class="doc-files">${d.files.map((f,i)=>`<button class="file-chip" type="button" onclick="previewFile(${d.id},${i})">${esc(f.name)}</button>`).join('')}</div>`:'<span class="small-muted">—</span>'}
    function actions(d){if(d.status==='DRAFT')return `<div class="row-actions"><button class="btn primary small" onclick="postAction('send',${d.id})">ສົ່ງ</button><button class="btn primary small" onclick="viewDoc(${d.id})">ເບິ່ງ</button><button class="btn danger small" onclick="postAction('delete',${d.id})">ລຶບ</button></div>`; if(['WAITING','QWAIT'].includes(d.status))return `<div class="row-actions"><button class="btn primary small" onclick="viewDoc(${d.id})">ເບິ່ງ</button><button class="btn danger small" onclick="postAction('cancel',${d.id})">ຍົກເລີກ</button></div>`; if(d.status==='CANCEL')return `<div class="row-actions"><button class="btn primary small" onclick="viewDoc(${d.id})">ເບິ່ງ</button><button class="btn danger small" onclick="postAction('delete',${d.id})">ລຶບ</button></div>`; return `<div class="row-actions"><button class="btn primary small" onclick="viewDoc(${d.id})">ເບິ່ງ</button></div>`}
	    function setTableLoading(on){state.loading=on; $('#tableLoading').classList.toggle('show',on); $('#prevPage').disabled=on||state.pagination.current_page<=1; $('#nextPage').disabled=on||state.pagination.current_page>=state.pagination.last_page;}
	    function render(){const shown=documents, page=state.pagination; $('#docEmpty').textContent='ບໍ່ພົບເອກະສານ'; $('#docEmpty').classList.toggle('show',!shown.length&&!state.loading); $('#docRows').innerHTML=shown.map(d=>`<tr><td><div class="doc-no">${esc(d.no)}</div><div class="small-muted">${d.vehicles} ຄັນ</div></td><td>${chip(d.status)}</td><td class="small-muted">${esc(d.dateIn||'—')}</td><td class="small-muted">${esc(d.dateOut||'—')}</td><td>${esc(d.destination||'—')}${d.note?`<div class="small-muted">${esc(d.note)}</div>`:''}</td><td>${files(d)}</td><td>${actions(d)}</td></tr>`).join(''); $('#docCards').innerHTML=shown.map(d=>`<article class="doc-card"><div class="doc-card-head"><div><div class="doc-no">${esc(d.no)}</div><div class="small-muted">${d.vehicles} ຄັນ</div></div>${chip(d.status)}</div><p>${esc(d.destination||'—')}</p>${d.note?`<p class="small-muted">${esc(d.note)}</p>`:''}<dl class="doc-dates"><div><dt class="small-muted">ວັນທີເຂົ້າ</dt><dd>${esc(d.dateIn||'—')}</dd></div><div><dt class="small-muted">ວັນທີອອກ</dt><dd>${esc(d.dateOut||'—')}</dd></div></dl><div style="margin-top:12px">${files(d)}</div><div style="margin-top:12px">${actions(d)}</div></article>`).join(''); $('#pageText').textContent=page.total?`ສະແດງ ${page.from}-${page.to} ຈາກ ${page.total}`:'ສະແດງ 0 ຈາກ 0'; $('#pageNumber').textContent=`${page.current_page}/${page.last_page}`; $('#prevPage').disabled=state.loading||page.current_page<=1; $('#nextPage').disabled=state.loading||page.current_page>=page.last_page; }
	    async function loadDocuments(page=1){state.page=page; setTableLoading(true); const params=new URLSearchParams({page:String(page),scope:state.scope,filter:state.filter,q:state.q}); try{const res=await fetch(`${routes.data}?${params.toString()}`,{headers:{'Accept':'application/json'},credentials:'same-origin'}); const data=await res.json().catch(()=>({})); if(!res.ok) throw data; documents=data.data||[]; state.pagination=data.pagination||{current_page:1,last_page:1,total:0,from:null,to:null}; render();}catch(e){documents=[]; state.pagination={current_page:1,last_page:1,total:0,from:null,to:null}; render(); $('#docEmpty').textContent=e.message||'ບໍ່ສາມາດໂຫຼດຂໍ້ມູນໄດ້'; $('#docEmpty').classList.add('show');}finally{setTableLoading(false);}}
	    function askAction(action){ const copy={send:'ສົ່ງ Draft ນີ້ເຂົ້າຂະບວນການ?',cancel:'ຕ້ອງການຍົກເລີກເອກະສານນີ້?',delete:'ຕ້ອງການລຶບເອກະສານນີ້?'}; $('#confirmText').textContent=copy[action]||'ຢືນຢັນການດຳເນີນການ?'; $('#confirmModal').classList.add('show'); return new Promise(resolve=>{ $('#confirmYes').onclick=()=>{ $('#confirmModal').classList.remove('show'); resolve(true); }; $('#confirmNo').onclick=()=>{ $('#confirmModal').classList.remove('show'); resolve(false); }; }); }
	    async function postAction(action,id){ if(!await askAction(action))return; fetch(routes[action],{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({id})}).then(async r=>{const d=await r.json().catch(()=>({})); if(!r.ok)throw d; $('#feedbackTitle').textContent='ສຳເລັດ'; $('#feedbackText').textContent=d.message||'ດຳເນີນການສຳເລັດ'; $('#feedbackModal').dataset.reload='1'; $('#feedbackModal').classList.add('show');}).catch(e=>{ $('#feedbackTitle').textContent='ບໍ່ສຳເລັດ'; $('#feedbackText').textContent=e.message||'ດຳເນີນການບໍ່ສຳເລັດ'; $('#feedbackModal').dataset.reload='0'; $('#feedbackModal').classList.add('show'); }); }
	    function viewDoc(id){const d=documents.find(x=>Number(x.id)===Number(id)); if(!d)return; const rows=(d.details||[]).map((x,i)=>`<article class="vehicle-item"><div class="vehicle-reference"><div><span class="vehicle-reference-label">ເລກອ້າງອີງ</span><span class="vehicle-reference-value">${esc(x.reference||'—')}</span></div><span class="vehicle-count">ລົດຄັນທີ ${i+1}</span></div><div class="vehicle-fields"><div class="vehicle-field"><span class="vehicle-label">ທະບຽນລົດ</span><span class="vehicle-value">${esc(x.plate||'—')}</span></div><div class="vehicle-field"><span class="vehicle-label">ຜູ້ຂັບ</span><span class="vehicle-value">${esc(x.driver||'—')}</span></div><div class="vehicle-field"><span class="vehicle-label">ປະເພດລົດ</span><span class="vehicle-value">${esc(x.type||'—')}</span></div><div class="vehicle-field"><span class="vehicle-label">ຈຳນວນຖ້ຽວ</span><span class="vehicle-value">${esc(x.rounds||'—')}</span></div><div class="vehicle-field"><span class="vehicle-label">ສິນຄ້າ</span><span class="vehicle-value">${esc(x.product||'—')}</span></div><div class="vehicle-field"><span class="vehicle-label">ນ້ຳໜັກ</span><span class="vehicle-value">${esc(x.weight||'—')}</span></div></div></article>`).join('')||'<div class="empty-state show">ບໍ່ມີລາຍການລົດ</div>'; $('#viewBody').innerHTML=`<div class="doc-modal-head"><div><h2 class="doc-modal-title">${esc(d.no)}</h2><div class="small-muted">${esc(d.vehicles)} ຄັນ</div></div>${chip(d.status)}</div><div class="summary-grid"><div class="summary-item"><span class="summary-label">ວັນທີເຂົ້າ</span><span class="summary-value">${esc(d.dateIn||'—')}</span></div><div class="summary-item"><span class="summary-label">ວັນທີອອກ</span><span class="summary-value">${esc(d.dateOut||'—')}</span></div><div class="summary-item"><span class="summary-label">ປາຍທາງ</span><span class="summary-value">${esc(d.destination||'—')}</span></div></div>${d.note?`<div class="summary-item"><span class="summary-label">ໝາຍເຫດ</span><span class="summary-value">${esc(d.note)}</span></div>`:''}<section class="detail-section"><h3 class="detail-section-title">ລາຍການລົດ</h3><div class="vehicle-list">${rows}</div></section><section class="detail-section"><h3 class="detail-section-title">ໄຟລ໌ແນບ</h3>${files(d)}</section>`; $('#viewModal').classList.add('show');}
	    let previewUrl=null, previewTimer=null;
	    function setPreviewProgress(value){const pct=Math.max(0,Math.min(100,Math.round(value))); $('#previewProgress').style.width=pct+'%'; $('#previewPercent').textContent=pct+'%'; if(pct>=100&&previewTimer){clearInterval(previewTimer);previewTimer=null;}}
	    function resetPreview(){if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;} if(previewTimer){clearInterval(previewTimer);previewTimer=null;} $('#previewContent').innerHTML=''; $('#previewLoader').classList.remove('hidden'); setPreviewProgress(0);}
	    function startFallbackProgress(){let pct=8; setPreviewProgress(pct); previewTimer=setInterval(()=>{pct=Math.min(92,pct+Math.max(1,Math.round((92-pct)*.14))); setPreviewProgress(pct); if(pct>=92) clearInterval(previewTimer);},240);}
	    async function loadPreviewBlob(file){resetPreview(); startFallbackProgress(); const res=await fetch(file.url,{credentials:'same-origin'}); if(!res.ok) throw new Error('ບໍ່ສາມາດໂຫຼດໄຟລ໌ໄດ້'); const total=Number(res.headers.get('content-length'))||0; if(!res.body){const blob=await res.blob(); setPreviewProgress(100); return blob;} const reader=res.body.getReader(); const chunks=[]; let received=0; while(true){const {done,value}=await reader.read(); if(done) break; chunks.push(value); received+=value.length; if(total) setPreviewProgress((received/total)*92);} const blob=new Blob(chunks,{type:res.headers.get('content-type')||''}); setPreviewProgress(96); return blob;}
	    async function previewFile(docId,fileIndex){const d=documents.find(x=>Number(x.id)===Number(docId)); const file=d?.files?.[fileIndex]; if(!file)return; $('#previewTitle').textContent=file.name||'ເບິ່ງໄຟລ໌'; $('#previewSub').textContent='ກຳລັງໂຫຼດ...'; $('#previewOpen').href=file.url; $('#filePreviewModal').classList.add('show'); try{const blob=await loadPreviewBlob(file); previewUrl=URL.createObjectURL(blob); const isPdf=(file.kind==='pdf') || blob.type.includes('pdf') || /\.pdf($|\?)/i.test(file.name||file.url); const isImage=(file.kind==='img') || blob.type.startsWith('image/') || /\.(jpg|jpeg|png|gif|webp)($|\?)/i.test(file.name||file.url); if(isPdf){$('#previewSub').textContent='PDF Preview'; $('#previewContent').innerHTML=`<iframe class="preview-frame" title="${esc(file.name)}" src="${previewUrl}#view=Fit&page=1"></iframe>`; $('#previewContent iframe').addEventListener('load',()=>{$('#previewLoader').classList.add('hidden');setPreviewProgress(100);},{once:true}); setTimeout(()=>{$('#previewLoader').classList.add('hidden');setPreviewProgress(100);},900);} else if(isImage){$('#previewSub').textContent='Image Preview'; const img=new Image(); img.className='preview-image'; img.alt=file.name||'preview'; img.onload=()=>{$('#previewLoader').classList.add('hidden');setPreviewProgress(100);}; img.onerror=()=>{$('#previewSub').textContent='Preview unavailable'; $('#previewContent').innerHTML=`<div class="preview-error">ຮູບພາບນີ້ສະແດງບໍ່ໄດ້. ກະລຸນາເປີດໃນ Tab.</div>`; $('#previewLoader').classList.add('hidden');setPreviewProgress(100);}; img.src=previewUrl; $('#previewContent').appendChild(img);} else {$('#previewSub').textContent='Preview unavailable'; $('#previewContent').innerHTML=`<div class="preview-error">ປະເພດໄຟລ໌ນີ້ບໍ່ຮອງຮັບ preview. ກະລຸນາເປີດໃນ Tab.</div>`; $('#previewLoader').classList.add('hidden');setPreviewProgress(100);}}catch(e){$('#previewSub').textContent='ໂຫຼດບໍ່ສຳເລັດ'; $('#previewContent').innerHTML=`<div class="preview-error">${esc(e.message||'ບໍ່ສາມາດ preview ໄຟລ໌ໄດ້')}</div>`; $('#previewLoader').classList.add('hidden');setPreviewProgress(100);}}
			    let searchTimer=null; $$('[data-scope]').forEach(b=>b.onclick=()=>{state.scope=b.dataset.scope;$$('[data-scope]').forEach(x=>x.classList.toggle('active',x===b));loadDocuments(1)}); $$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));loadDocuments(1)}); $('#docSearch').oninput=e=>{state.q=e.target.value; clearTimeout(searchTimer); searchTimer=setTimeout(()=>loadDocuments(1),350)}; $('#prevPage').onclick=()=>{if(state.pagination.current_page>1)loadDocuments(state.pagination.current_page-1)}; $('#nextPage').onclick=()=>{if(state.pagination.current_page<state.pagination.last_page)loadDocuments(state.pagination.current_page+1)}; $('#closeView').onclick=()=>$('#viewModal').classList.remove('show'); $('#closePreview').onclick=()=>{ $('#filePreviewModal').classList.remove('show'); resetPreview(); }; $('#feedbackOk').onclick=()=>{ const shouldReload=$('#feedbackModal').dataset.reload==='1'; $('#feedbackModal').classList.remove('show'); if(shouldReload) loadDocuments(state.pagination.current_page); }; $('#menuBtn').onclick=()=>{const open=$('#mobileNav').classList.toggle('open');document.body.classList.toggle('nav-open',open)}; $('#pageBackdrop').onclick=()=>{ $('#mobileNav').classList.remove('open'); document.body.classList.remove('nav-open')}; loadDocuments(1);
	    window.postAction=postAction; window.viewDoc=viewDoc; window.previewFile=previewFile;
  </script>
</body>
</html>
